import java.util.*;import com.google.common.collect.*;import net.minecraft.item.*;import net.minecraft.entity.*;import net.minecraft.entity.ai.attributes.*;import net.minecraft.inventory.EntityEquipmentSlot;import net.minecraft.nbt.*;import net.minecraftforge.common.util.EnumHelper;
public class NativeToolAttributeTest extends ProductionToolProjections {
 static int assertions;static final String DAMAGE=SharedMonsterAttributes.ATTACK_DAMAGE.getName(),SPEED=SharedMonsterAttributes.ATTACK_SPEED.getName(),MOVE=SharedMonsterAttributes.MOVEMENT_SPEED.getName();static final UUID ID=UUID.fromString("cb3f55d3-645c-4f38-a497-9c13a33db5cf");
 static void check(boolean b,String m){assertions++;if(!b)throw new AssertionError(m);}static void eq(double a,double b,String m){check(Double.doubleToLongBits(a)==Double.doubleToLongBits(b),m+": "+a+" != "+b);}
 static AttributeModifier one(Multimap m,String key){Collection<AttributeModifier> a=m.get(key);check(a.size()==1,"one "+key+" got "+a.size());return a.iterator().next();}
 static void modifier(Multimap m,String key,String name,double value,int op){AttributeModifier a=one(m,key);check(a.getID().equals(ID),"original shared UUID "+key);check(a.getName().equals(name),"name "+key);eq(a.getAmount(),value,"amount "+key);check(a.getOperation()==op,"operation "+key);}
 static void same(Multimap a,Multimap b,String why){check(a.keySet().equals(b.keySet()),why+" keys");for(Object key:a.keySet()){Collection<AttributeModifier>x=a.get(key),y=b.get(key);check(x.size()==y.size(),why+" size");for(AttributeModifier v:x){AttributeModifier w=null;for(AttributeModifier z:y)if(z.getID().equals(v.getID()))w=z;check(w!=null,why+" UUID");eq(v.getAmount(),w.getAmount(),why+" amount");check(v.getOperation()==w.getOperation(),why+" operation");check(v.getName().equals(w.getName()),why+" name");}}}
 static Item.ToolMaterial[] materials(){List<Item.ToolMaterial> m=new ArrayList<>(Arrays.asList(Item.ToolMaterial.values()));float[] damage={0.5F,2F,12F,26F,100F,1000000000F,16777212F,16777214F,16777216F};for(int i=0;i<damage.length;i++)m.add(EnumHelper.addToolMaterial("CP92_PROBE_"+i,2,100,6F,damage[i],10));return m.toArray(new Item.ToolMaterial[0]);}
 static void abilities(Item.ToolMaterial[] materials){for(Item.ToolMaterial m:materials)for(float damage:new float[]{0,2,6.5F,35,75,5000})for(double movement:new double[]{-0.1,0,0.5,1}){
  for(int k=0;k<3;k++){Item item=k==0?new ItemSwordAbility(damage,movement,m):k==1?new ItemToolAbility(damage,movement,m,ItemToolAbility.EnumToolType.PICKAXE):new ItemCrucible(damage,movement,m);ItemStack stack=new ItemStack(item);for(int wear:new int[]{0,Math.max(0,item.getMaxDamage()-1),item.getMaxDamage()}){stack.setItemDamage(wear);for(EntityEquipmentSlot slot:EntityEquipmentSlot.values()){Multimap map=stack.getAttributeModifiers(slot);same(map,item.getAttributeModifiers(slot,stack),"stack-sensitive virtual hook");boolean active=slot!=EntityEquipmentSlot.OFFHAND&&(k!=2||wear<stack.getMaxDamage());check(map.size()==(active?2:0),"ability map size and depleted Crucible boundary");check(!map.containsKey(SPEED),"no invented attack speed for replacement maps");if(active){modifier(map,DAMAGE,"Tool modifier",damage,0);modifier(map,MOVE,"Tool modifier",movement,1);}}}}
 }}
 static void simple(){for(int kind=0;kind<5;kind++){Item item=kind==0?new ItemMirrorTool():kind==1?new ItemRBMKTool():kind==2?new GunB92():new ItemToolingWeapon(kind==3?7.5F:12F);ModItems.wrench=kind==3?item:null;ItemStack stack=new ItemStack(item);for(EntityEquipmentSlot slot:EntityEquipmentSlot.values()){Multimap map=stack.getAttributeModifiers(slot);same(map,item.getAttributeModifiers(slot,stack),"simple bridge");int count=slot==EntityEquipmentSlot.OFFHAND?0:kind==3?2:1;check(map.size()==count,"simple map size");if(count>0)modifier(map,DAMAGE,"Weapon modifier",kind<2?2:kind==2?3.5:kind==3?7.5:12,0);if(kind==3&&count>0)modifier(map,MOVE,"Wrench modifier",-0.1,1);}}}
 static void special(Item.ToolMaterial[] materials){for(Item.ToolMaterial m:materials)for(int identity=0;identity<6;identity++){
  WeaponSpecial item=new WeaponSpecial(m);ModItems.schrabidium_hammer=identity==0?item:null;ModItems.shimmer_sledge=identity==1?item:null;ModItems.shimmer_axe=identity==2?item:null;ModItems.wrench_flipped=identity==3?item:null;ItemStack stack=new ItemStack(item);ItemSword nativeBase=new ItemSword(m);
  for(EntityEquipmentSlot slot:EntityEquipmentSlot.values()){Multimap map=stack.getAttributeModifiers(slot);same(map,item.getAttributeModifiers(slot,stack),"special bridge");boolean custom=identity<4&&slot!=EntityEquipmentSlot.OFFHAND;int count=(slot==EntityEquipmentSlot.MAINHAND?2:0)+(custom?1:0);check(map.size()==count,"special native baseline and exact custom map");if(slot==EntityEquipmentSlot.MAINHAND){modifier(map,DAMAGE,"Weapon modifier",(double)(4.0F+m.getAttackDamage()),0);Multimap a=HashMultimap.create(),b=HashMultimap.create();a.putAll(SPEED,map.get(SPEED));b.putAll(SPEED,nativeBase.getItemAttributeModifiers(slot).get(SPEED));same(a,b,"retain genuine native attack speed");}else check(!map.containsKey(DAMAGE)&&!map.containsKey(SPEED),"native Sword baseline slot applicability");if(custom)modifier(map,MOVE,"Weapon modifier",identity==0?-0.5:identity==3?-0.1:-0.2,1);}
 }}
 static final UUID MARKER=UUID.fromString("efea2fe2-bec2-4575-9368-b019a88fe3a3");static EntityEquipmentSlot seen;static Multimap mark(EntityEquipmentSlot s){seen=s;Multimap m=HashMultimap.create();m.put(SharedMonsterAttributes.MAX_HEALTH.getName(),new AttributeModifier(MARKER,"virtual marker",1,0));return m;}
 static void virtual(){Item[] items={new ItemMirrorTool(){public Multimap getItemAttributeModifiers(EntityEquipmentSlot s){return mark(s);}},new ItemRBMKTool(){public Multimap getItemAttributeModifiers(EntityEquipmentSlot s){return mark(s);}},new ItemToolingWeapon(7){public Multimap getItemAttributeModifiers(EntityEquipmentSlot s){return mark(s);}}};for(Item item:items)for(EntityEquipmentSlot slot:EntityEquipmentSlot.values()){seen=null;Multimap map=item.getAttributeModifiers(slot,new ItemStack(item));check(seen==slot,"preserve supplied slot through native virtual bridge");check(map.containsKey(SharedMonsterAttributes.MAX_HEALTH.getName()),"super virtual payload retained");}}
 static void originalParity(){for(int i=0;i<ORIGINAL_NAMES.length;i++){String name=ORIGINAL_NAMES[i];float originalDamage=5000;double originalMovement=1;for(String[] row:ORIGINAL_PAYLOADS[i]){if(row[0].equals(DAMAGE))originalDamage=Float.parseFloat(row[3]);if(row[0].equals(MOVE))originalMovement=Double.parseDouble(row[3]);}Item item=name.contains("ItemCrucible")?new ItemCrucible(originalDamage,originalMovement,Item.ToolMaterial.IRON):name.endsWith("GunB92")?new GunB92():new ItemSwordAbility(originalDamage,originalMovement,Item.ToolMaterial.IRON);item.setMaxDamage(3);ItemStack stack=new ItemStack(item);if(name.contains("/damage="))stack.setItemDamage(Integer.parseInt(name.substring(name.indexOf('=')+1)));for(EntityEquipmentSlot slot:EntityEquipmentSlot.values()){Multimap map=stack.getAttributeModifiers(slot);check(map.size()==(slot==EntityEquipmentSlot.OFFHAND?0:ORIGINAL_PAYLOADS[i].length),"actual original map size "+name);if(slot!=EntityEquipmentSlot.OFFHAND)for(String[] row:ORIGINAL_PAYLOADS[i]){AttributeModifier a=one(map,row[0]);check(a.getID().toString().equals(row[1]),"actual original UUID");check(a.getName().equals(row[2]),"actual original name");eq(a.getAmount(),Double.parseDouble(row[3]),"actual original amount");check(a.getOperation()==Integer.parseInt(row[4]),"actual original operation");}}}}
 static void nbtAndGauntlet(){check(!gauntletHeldCheck(null),"nullable held gate");check(!gauntletHeldCheck(new ItemStack(new Item())),"ordinary nonweapon gate");ItemCrucible item=new ItemCrucible(5000,1,Item.ToolMaterial.IRON);ItemStack stack=new ItemStack(item);check(gauntletHeldCheck(stack),"charged Crucible blocks gauntlet");stack.setItemDamage(stack.getMaxDamage());check(!gauntletHeldCheck(stack),"spent Crucible permits gauntlet");NBTTagCompound root=new NBTTagCompound();NBTTagList list=new NBTTagList();NBTTagCompound modifier=SharedMonsterAttributes.writeAttributeModifierToNBT(new AttributeModifier(UUID.fromString("d638986e-2c2e-40f2-b468-d0c14c6132f9"),"explicit ordinary tag",2,0));modifier.setString("AttributeName",DAMAGE);modifier.setString("Slot","mainhand");list.appendTag(modifier);root.setTag("AttributeModifiers",list);stack.setTagCompound(root);check(gauntletHeldCheck(stack),"gauntlet retains native ItemStack NBT override");check(stack.getAttributeModifiers(EntityEquipmentSlot.MAINHAND).size()==1,"NBT replaces item map");check(stack.getAttributeModifiers(EntityEquipmentSlot.OFFHAND).isEmpty(),"NBT mainhand slot filtering");modifier.setString("Slot","offhand");check(!gauntletHeldCheck(stack),"gauntlet queries mainhand not offhand");}
 public static void main(String[]args){net.minecraft.init.Bootstrap.register();Item.ToolMaterial[] materials=materials();abilities(materials);simple();special(materials);virtual();originalParity();nbtAndGauntlet();System.out.println("PASS native tool attributes: "+assertions+" assertions; 8 complete method projections, 3 constructor projections, actual native Item/Sword/Tool/ItemStack dispatch and NBT");}
}
